export function parsePokemonMeta(metaId) {
  const parts = String(metaId).split('/');
  const dexNum = Number.parseInt(parts[0], 10);
  const dexNumberStr = `#${String(dexNum).padStart(3, '0')}`;

  let variantTag = null;
  if (parts.length === 2) {
    variantTag = 'FORM';
  } else if (parts.length >= 3) {
    if (parts[1] === '0000' && parts[2] === '0001') {
      variantTag = '★ SHINY';
    } else if (parts[2] === '0001') {
      variantTag = '★ SHINY FORM';
    } else {
      variantTag = 'FORM';
    }
  }

  return { dexNum, dexNumberStr, variantTag };
}
